        return;
    case 0x00:	
    case 0x14:	
    case 0x40:	
    case 0x44:	
    case 0x80:	
    case 0x98:	
    case 0x9c:	
        OMAP_RO_REG(addr);
        return;
    }
    OMAP_BAD_REG(addr);
}

