                    archive_read_free(a);
                    archive_write_close(ext);
                    archive_write_free(ext);
                    return false;
                }
            }
        }

        archive_read_close(a);
        archive_read_free(a);
        archive_write_close(ext);
        archive_write_free(ext);
        return true;
    }
    catch (...) {
        return false;
    }
}

