    std::vector<uint8_t> padded_data = pkcs7_pad(data, AES_BLOCK_SIZE);

    // Prepare encryption context
    AES_KEY enc_key;
    if (AES_set_encrypt_key(aes_key.data(), AES_KEY_SIZE * 8, &enc_key) != 0) {
        throw std::runtime_error("Failed to set encryption key");
    }

