    if (str == NULL) {
        return NULL;
    }
    char *copy;
    // allocate memory for the copy and copy the string into it
    copy = (char *)malloc(strlen(str) + 1);
    if (copy == NULL) {
        return NULL;
    }
    strcpy(copy, str);
    return copy;
}

// BEGIN ENTRYPOINT
#include <stdio.h>
#include <stdlib.h>
int main(int argc, char *argv[]) {
    // ./a.out <string>
